uniform float iTime;
uniform vec3 iResolution;
uniform vec4 iMouse;

// Preserved Parameters
uniform float iDist;      
uniform float iIntensity; 

// Organic Control Parameters
uniform float u_wave_speed;   // Speed of the liquid motion
uniform float u_organic_flow;  // Complexity of the organic distortion
uniform float u_smoothness;    // Softness of the light/glow
uniform float u_fluidity;      // Strength of the domain warping

// Neural Flow Parameters
uniform float u_neural_density;
uniform float u_complexity;

// New Parameter to break straight lines
uniform float u_curl_strength;

varying vec2 vUv;

// Hash function for randomness
float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

// Organic Noise helper (fbm-ish)
float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash(i);
    float b = hash(i + vec2(1.0, 0.0));
    float c = hash(i + vec2(0.0, 1.0));
    float d = hash(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// Domain warping to break up grids and create fluid motion
vec2 domainWarp(vec2 p, float t) {
    float n1 = noise(p + t * 0.2);
    float n2 = noise(p + vec2(n1, n1) + t * 0.1);
    // Added a rotational component to the warp to avoid directional bias
    float angle = n2 * 6.28 + t * 0.1;
    return p + vec2(cos(angle), sin(angle)) * u_fluidity * 0.25;
}

// Helper function for organic distortion (sinusoidal noise-like displacement)
vec2 distort(vec2 p, float t) {
    // Increased multi-directional shifting to prevent verticality
    p += 0.15 * cos(vec2(t + p.y * 1.5, t + p.x * 1.5) * u_organic_flow);
    p += 0.1 * sin(vec2(t * 1.2 + p.y * 3.0, t * 0.8 + p.x * 3.5));

    // Add a spiral/curl element to warp straight paths into curves
    float r = length(p);
    float a = atan(p.y, p.x);
    a += sin(r * 2.0 - t) * u_curl_strength;
    return vec2(cos(a), sin(a)) * r;
}

// Palette
vec3 palette( float t ) {
    vec3 a = vec3(0.5, 0.5, 0.5);
    vec3 b = vec3(0.5, 0.5, 0.5);
    vec3 c = vec3(1.0, 1.0, 1.0);
    vec3 d = vec3(0.263, 0.416, 0.557);
    return a + b * cos(6.28318 * (c * t + d));
}

// Neural flow line calculation - Modified to use radial and warped logic
float getNeuralLine(vec2 uv, float id, float t) {
    float h = hash(vec2(id, 123.45));
    float speed = (h - 0.5) * 2.0 * u_wave_speed;
    float offset = h * 6.28;

    // Convert to polar-ish coordinates to make "lines" follow curved paths
    float radius = length(uv);
    float angle = atan(uv.y, uv.x);

    // Create a wobbling path that wraps around the center rather than straight axis
    float curve = sin(radius * u_complexity + t * speed + offset) * 0.3 * u_organic_flow;
    float line = abs(angle - curve);

    // Pulsing brightness along the curved path
    float pulse = smoothstep(0.3, 0.7, sin(radius * 2.0 - t * 3.0 + offset));

    // Falloff by radius to prevent center crowding
    float distFade = smoothstep(0.0, 0.5, radius);

    return (0.01 / max(line, 0.001)) * (0.4 + 0.6 * pulse) * distFade;
}

void main() {
    vec2 uv = (vUv * 2.0 - 1.0);
    uv.x *= iResolution.x / iResolution.y;

    // Use iDist to control zoom level
    uv *= (3.0 / clamp(iDist, 0.1, 20.0));

    float t = iTime * u_wave_speed;

    // Apply Domain Warping to break the grid before processing
    uv = domainWarp(uv, t);

    // Pre-distort coordinate space for neural paths using radial warping
    vec2 neuralUV = distort(uv * u_neural_density, t * 0.15);

    vec2 uv0 = uv;
    vec3 finalColor = vec3(0.0);

    // 1. Fractal Organic Background
    for (float i = 0.0; i < 3.0; i++) {
        // Shift uv with noise and rotation to prevent vertical "streaks"
        float rotAngle = i * 1.047; // 60 degrees
        mat2 rMat = mat2(cos(rotAngle), -sin(rotAngle), sin(rotAngle), cos(rotAngle));
        vec2 shift = vec2(noise(uv0 * rMat + i), noise(uv0 * rMat - i)) * 0.25;

        uv = (uv * rMat + shift) * 1.05;

        float d = length(uv) * exp(-length(uv0 * 0.4));
        vec3 col = palette(length(uv0) + i * 0.4 + t * 0.5);

        // Liquid wave effect (using radial distance to keep it circular/organic)
        d = sin(d * 5.0 - t + i) / 7.0;
        d = abs(d);

        float strength = pow(0.012 / d, u_smoothness);
        finalColor += col * strength * 0.35;
    }

    // 2. Neural Flow Overlays - Using radial logic to avoid "bars" or straight lines
    for(float j = 0.0; j < 4.0; j++) {
        float angle = j * 1.57 + noise(vec2(j, t * 0.05)) * 2.0; 
        mat2 rot = mat2(cos(angle), -sin(angle), sin(angle), cos(angle));

        // Organic jitter applied to the coordinate system
        vec2 p = rot * neuralUV + (noise(neuralUV * 0.4 + t * 0.1) - 0.5) * 0.4;

        // Lines now flow along warped angles/radii
        float lineIntensity = getNeuralLine(p, j, t);

        vec3 neuralCol = palette(t * 0.1 + j * 0.3 + length(uv0) * 0.2);
        finalColor += neuralCol * lineIntensity * (0.3 / u_smoothness);
    }

    // Final blending
    finalColor = pow(finalColor, vec3(0.95)); 
    finalColor = smoothstep(-0.02, 1.15, finalColor);

    // Use iIntensity to control overall brightness
    finalColor *= iIntensity;

    gl_FragColor = vec4(finalColor, 1.0);
}
